class Bitset {
    vector<char> bits;
    int n;
    int ones;
    bool flipped;
public:
    Bitset(int size) : bits(size, 0), n(size), ones(0), flipped(false) {

    }

    void fix(int idx) {
        if (!flipped) {
            if (bits[idx] == 0) {
                bits[idx] = 1;
                ones++;
            }
        } else {
            if (bits[idx] == 1) {
                bits[idx] = 0;
                ones--;
            }
        }
    }

    void unfix(int idx) {
        if (!flipped) {
            if (bits[idx] == 1) {
                bits[idx] = 0;
                ones--;
            }
        } else {
            if (bits[idx] == 0) {
                bits[idx] = 1;
                ones++;
            }
        }
    }

    void flip() {
        flipped = !flipped;
    }

    bool all() {
        return count() == n;
    }

    bool one() {
        return count() > 0;
    }

    int count() {
        return flipped ? (n - ones) : ones;
    }

    string toString() {
        string res(n, '0');
        for (int i = 0; i < n; i++) {
            char logical = flipped ? (1 - bits[i]) : bits[i];
            res[i] = logical ? '1' : '0';
        }
        return res;
    }
};
